/* C API of the Rust port of `oneshot_crc.c`, generated by everything-rust. */
#ifndef ONESHOT_CRC_RS_H
#define ONESHOT_CRC_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

uint32_t oneshot_crc(int id, uint32_t crc, const uint8_t *buf, size_t len);
int64_t oneshot_crc_custom(int le, int bits, uint32_t poly, int table_size, uint32_t crc, const uint8_t *buf, size_t len);

/* The same functions under `everything_rust_` names, for shadow runs. */
uint32_t everything_rust_oneshot_crc(int id, uint32_t crc, const uint8_t *buf, size_t len);
int64_t everything_rust_oneshot_crc_custom(int le, int bits, uint32_t poly, int table_size, uint32_t crc, const uint8_t *buf, size_t len);

#endif /* ONESHOT_CRC_RS_H */
